-- A diagram keeps its immutable layout instrument while this relation records
-- every compatible instrument through which the same diagram is available.
CREATE TABLE "diagram_instruments" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "linked_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "diagram_id" uuid NOT NULL, "instrument_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "diagram_instruments_diagrams_diagram" FOREIGN KEY ("diagram_id") REFERENCES "diagrams" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "diagram_instruments_instruments_instrument" FOREIGN KEY ("instrument_id") REFERENCES "instruments" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
CREATE UNIQUE INDEX "diagraminstrument_diagram_id_instrument_id" ON "diagram_instruments" ("diagram_id", "instrument_id");

-- Existing diagrams remain available through their current layout instrument.
INSERT INTO "diagram_instruments" ("diagram_id", "instrument_id")
SELECT "id", "instrument_id" FROM "diagrams";
